def match_parens(lst):
    # Verify the input list contains exactly two strings
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    # Verify both strings consist of only '(' or ')' parentheses
    if any(c not in ['(', ')'] for s in lst for c in s):
        return 'No'

    # Concatenate the two strings
    concatenated = lst[0] + lst[1]

    # Check if all parentheses are balanced in the concatenated string
    stack = []
    for char in concatenated:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    # Return 'Yes' if a good string can be formed, and 'No' otherwise
    return 'Yes' if not stack else 'No'

